const rows = items.map(function(i) { return i.json; });
const pending = rows.filter(function(r) { return r['상태'] === '대기중'; });
if (pending.length === 0) return [{ json: { found: false } }];
const row = pending[0];
return [{
  json: {
    found: true,
    메인키워드: row['메인 키워드'] || '',
    서브키워드: row['서브키워드'] || '',
    서브수: parseInt(row['서브키워드 수']) || 3,
    참조키워드: row['참조키워드'] || '',
    연결링크: row['연결링크'] || ''
  }
}];

const d = items[0].json;
const keyword = d.메인키워드;
const subKeywords = d.서브키워드;
const subCount = d.서브수;
const refKeyword = d.참조키워드;
const refLink = d.연결링크;

// ── 카테고리 자동 분류 (TODO: Astro config.ts 실제 enum 값으로 교체) ──
var category;
if (keyword.indexOf('상속세') !== -1 || keyword.indexOf('상속공제') !== -1 || keyword.indexOf('일괄공제') !== -1 || keyword.indexOf('배우자공제') !== -1 || keyword.indexOf('상속세율') !== -1 || keyword.indexOf('상속세 신고') !== -1) {
  category = 'inheritance-tax';
} else if (keyword.indexOf('증여') !== -1 || keyword.indexOf('증여세') !== -1 || keyword.indexOf('증여공제') !== -1 || keyword.indexOf('사전증여') !== -1) {
  category = 'gift-tax';
} else if (keyword.indexOf('상속') !== -1 || keyword.indexOf('유산') !== -1 || keyword.indexOf('유언') !== -1 || keyword.indexOf('상속포기') !== -1 || keyword.indexOf('한정승인') !== -1 || keyword.indexOf('법정상속') !== -1) {
  category = 'inheritance';
} else if (keyword.indexOf('재산') !== -1 || keyword.indexOf('부동산') !== -1 || keyword.indexOf('아파트') !== -1 || keyword.indexOf('토지') !== -1) {
  category = 'property';
} else {
  category = 'general';
}

const author = '가족상속세무연구소 수석 세무사';

const today = new Date();
const dateStr = today.toISOString().split('T')[0];
const dateCompact = dateStr.replace(/-/g, '');
const slug = keyword
  .replace(/\s+/g, '-')
  .replace(/[^a-zA-Z0-9가-힣-]/g, '')
  .substring(0, 40) + '-' + dateCompact;

const systemPrompt = '[역할]\n'
  + '너는 상속세나 세무법을 전혀 모르는 평범한 이웃들에게 복잡한 세금 문제를 가장 쉽고 다정하게 풀어주는 "가족상속세무연구소의 수석 상속전문 세무사"야.\n'
  + '법률 전문가로서의 확실한 공신력과 전문성을 갖추되, 막막한 상황에 놓인 일반 납세자의 눈높이에서 명쾌한 해결책을 제시하는 독창적인 정보성 칼럼을 작성해줘.\n\n'
  + '[5대 글쓰기 원칙 - 가독성 및 오리지널리티 극대화]\n\n'
  + '1. 한국 사람이 일상에서 자연스럽게 쓸 법한 표현 사용\n'
  + '- 법률 조문이나 외국 세무 서적을 그대로 번역한 듯한 어색한 문체(예: "~를 고려에 넣어야 합니다", "우리는 ~한 리스크에 직면해 있습니다")는 절대 쓰지 마라.\n'
  + '- 실제 대한민국 세무사가 동네 주민이나 친근한 이웃에게 따뜻하게 조언하듯 매끄럽고 세련된 한국어 관용구와 일상 표현을 사용해줘.\n\n'
  + '2. 권위를 유지하되 부드럽고 유연한 어미 사용 (딱딱한 어투 전면 금지)\n'
  + '- "~하십시오", "~입니다", "~합니다", "~해야 합니다", "~됩니다", "~하도록 규정되어 있습니다" 같은 어투는 절대 쓰지 마라.\n'
  + '- 대신 "~해요", "~해보세요", "~편이 실무상 안전하답니다", "~를 권해 드려요" 등의 부드러운 경어체를 일관되게 사용해줘.\n\n'
  + '3. 능동태 중심의 주체적인 문장 구성\n'
  + '- 수동태나 피동형 표현(예: "세금이 부과당하게 됩니다", "재산이 상속되어집니다")을 전면 금지한다.\n'
  + '- 납세자와 세무 행정의 주체가 명확히 살아있는 능동태로 모든 문장을 구성해줘.\n\n'
  + '4. 호흡이 짧고 명확한 문장 배치 (복잡한 장문 금지)\n'
  + '- 한 문장에는 오직 하나의 세무 정보나 쟁점(One Sentence, One Issue)만 담아라.\n'
  + '- 문장이 길어지면 주저 없이 마침표를 찍고 두세 개의 짧은 문장으로 나누어 서술해줘.\n\n'
  + '5. "당신", "여러분" 호칭 전면 금지\n'
  + '- "우리 가족", "상속인", "납세자", "평범한 가정" 등으로 대체하고, 호칭이 생략 가능한 곳에서는 과감히 생략해줘.\n\n'
  + '[콘텐츠 방향]\n'
  + '- 고액 자산가의 복잡한 기업 승계나 세무 회피 기술은 제외해라.\n'
  + '- 아파트 한 채를 가진 평범한 중산층 가정이 갑작스러운 임종 후 세금 폭탄을 피하기 위해 반드시 알아야 할 기본 공제 혜택처럼 지극히 대중적이고 실용적인 주제를 다뤄줘.\n'
  + '- 단순한 세법 요약 나열을 피하고, 실제 일반 가정에서 신고 기한을 놓쳐 가산세를 무는 흔한 실수 사례를 스토리텔링식으로 구성해줘.\n\n'
  + '[출력 형식 규칙]\n'
  + '- 출력은 반드시 아래 5개 마커를 순서대로 포함할 것\n'
  + '- 마크다운 형식으로 작성 (HTML 태그 금지)\n'
  + '- 마커와 실제 내용 사이에 줄바꿈 없이 바로 내용 작성';

var refLinkInstruction = '';
if (refKeyword && refLink) {
  refLinkInstruction = '- 참조 링크도 본문 자연스러운 위치에 마크다운 형식으로 1회 삽입:\n'
    + '  [' + refKeyword + '](' + refLink + ')\n';
}

const userPrompt = '아래 조건으로 가족상속세무연구소 칼럼을 작성해줘.\n\n'
  + '[키워드 조건]\n'
  + '- 메인 키워드: ' + keyword + '\n'
  + '- 서브키워드: ' + subKeywords + '\n'
  + '- 서브키워드 각각 ' + subCount + '회 이상 자연스럽게 포함\n\n'
  + '[작성 지침]\n'
  + '- H2 소제목 4개 이상, 각 H2 아래 H3 소제목 2개씩\n'
  + '- 본문 전체 공백 제외 2,500자 이상\n'
  + '- "~합니다", "~입니다", "~해야 합니다", "~됩니다", "~하십시오" 절대 금지\n'
  + '- 실제 평범한 가정의 실수 사례를 스토리텔링 방식으로 1개 이상 포함\n'
  + refLinkInstruction
  + '\n[출력 형식] 아래 5개 마커를 반드시 포함:\n'
  + '##TITLE##여기에 SEO 최적화 제목 (60자 이내)\n'
  + '##META##여기에 메타 디스크립션 (120자 이내, 메인키워드 포함)\n'
  + '##AISUMMARY##여기에 AI 요약 (2~3문장, 핵심 내용 압축)\n'
  + '##TAGS##여기에 태그 (쉼표 구분, 5~7개)\n'
  + '##MARKDOWN##여기에 본문 전체 마크다운';

const gptBody = {
  model: 'gpt-4o',
  max_tokens: 8000,
  temperature: 0.8,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ]
};

return [{
  json: {
    keyword, subKeywords, subCount,
    category, author,
    refKeyword, refLink,
    slug, dateStr,
    gptBody
  }
}];

const gptResult = items[0].json;
const prevData = $('슬러그 생성 및 GPT 요청 준비').first().json;

const raw = gptResult.choices[0].message.content;

function extractMarker(text, marker) {
  var tag = '##' + marker + '##';
  var start = text.indexOf(tag);
  if (start === -1) return '';
  start = start + tag.length;
  var nextHash = text.indexOf('##', start);
  var end = nextHash === -1 ? text.length : nextHash;
  return text.substring(start, end).trim();
}

// MARKDOWN은 마지막 마커이므로 끝까지 전부 가져옴
var mdTag = '##MARKDOWN##';
var mdStart = raw.indexOf(mdTag);
var markdownContent = mdStart !== -1 ? raw.substring(mdStart + mdTag.length).trim() : raw;

var title = extractMarker(raw, 'TITLE') || prevData.keyword + ' 가족법 안내';
var metaDescription = extractMarker(raw, 'META') || prevData.keyword + ' 관련 법률 정보';
var aiSummary = extractMarker(raw, 'AISUMMARY') || '';
var tagsRaw = extractMarker(raw, 'TAGS') || prevData.keyword;

var tags = tagsRaw.split(',').map(function(t) { return t.trim(); }).filter(function(t) { return t.length > 0; });
var charCount = markdownContent.replace(/\s/g, '').length;
var readingTime = Math.max(5, Math.ceil(charCount / 500));

// 키워드 기반 이미지 설명 생성
var kw = prevData.keyword;
var imageDesc = '';

if (kw.indexOf('상속세') !== -1 || kw.indexOf('상속세율') !== -1 || kw.indexOf('공제') !== -1 || kw.indexOf('일괄공제') !== -1) {
  imageDesc = 'A warm and professional Korean tax consultation scene. A kind Korean tax accountant in his 50s sitting across from an elderly Korean couple in their 60s at a bright clean office desk. Tax documents, a calculator, and glasses on the table. Soft natural light, trustworthy and reassuring atmosphere. No text or letters in the image.';
} else if (kw.indexOf('증여') !== -1 || kw.indexOf('증여세') !== -1 || kw.indexOf('사전증여') !== -1) {
  imageDesc = 'A warm intergenerational Korean family scene. Elderly Korean parents in their 70s handing important documents to their adult child in their 40s at a bright family home. Warm afternoon light, family photos visible in background, caring and trusting atmosphere. No text or letters in the image.';
} else if (kw.indexOf('상속') !== -1 || kw.indexOf('유언') !== -1 || kw.indexOf('상속포기') !== -1 || kw.indexOf('한정승인') !== -1) {
  imageDesc = 'A thoughtful scene of a Korean family carefully reviewing legal documents around a dining room table. Warm indoor lighting, tea cups, a family home setting. Middle-aged Korean adults with a sense of careful deliberation and family unity. No text or letters in the image.';
} else if (kw.indexOf('아파트') !== -1 || kw.indexOf('부동산') !== -1 || kw.indexOf('재산') !== -1) {
  imageDesc = 'A professional Korean real estate and tax consultation. A Korean tax accountant reviewing property documents and a floor plan with a Korean couple in their 50s at a modern office. Bright clean space, documents and a laptop visible. Focused and competent atmosphere. No text or letters in the image.';
} else if (kw.indexOf('신고') !== -1 || kw.indexOf('기한') !== -1 || kw.indexOf('가산세') !== -1) {
  imageDesc = 'A focused Korean tax accountant in their 40s carefully reviewing important tax documents at a bright office desk. Calendar, calculator, official documents, and a pen visible. Deadline awareness, professional and calm atmosphere. No text or letters in the image.';
} else {
  imageDesc = 'A professional and welcoming Korean tax accounting firm office. Clean modern Korean interior, bookshelves with tax law reference books, natural plants, warm lighting, a consultation desk. Trustworthy family tax planning firm atmosphere. No text or letters in the image.';
}

var imageBody = {
  model: 'gpt-image-1',
  prompt: imageDesc + ' Photorealistic style, high quality.',
  n: 1,
  size: '1536x1024',
  quality: 'medium'
};

return [{
  json: {
    title: title,
    metaDescription: metaDescription,
    aiSummary: aiSummary,
    tags: tags,
    markdownContent: markdownContent,
    readingTime: readingTime,
    keyword: prevData.keyword,
    slug: prevData.slug,
    dateStr: prevData.dateStr,
    category: prevData.category,
    author: prevData.author,
    imageBody: imageBody
  }
}];

const prevData = $('GPT 응답 파싱 및 이미지 요청 준비').first().json;
const imageData = $('gpt-image-1: 이미지 생성').first().json;

const imageFilename = prevData.slug + '.png';
const imagePath = '/images/posts/' + imageFilename;

const tagsYaml = prevData.tags.map(function(t) {
  return '"' + t.replace(/"/g, "'") + '"';
}).join(', ');

const frontmatter = '---\n'
  + 'title: "' + prevData.title.replace(/"/g, "'") + '"\n'
  + 'summary: "' + prevData.metaDescription.replace(/"/g, "'") + '"\n'
  + 'date: ' + prevData.dateStr + '\n'
  + 'author: "' + prevData.author + '"\n'
  + 'tags: [' + tagsYaml + ']\n'
  + 'category: "' + prevData.category + '"\n'
  + 'aiSummary: "' + prevData.aiSummary.replace(/"/g, "'").replace(/\n/g, ' ') + '"\n'
  + 'readingTime: ' + prevData.readingTime + '\n'
  + 'ogImage: "' + imagePath + '"\n'
  + '---\n\n';

const imageMarkdown = '![' + prevData.title + '](' + imagePath + ')\n\n';
const fullMarkdown = frontmatter + imageMarkdown + prevData.markdownContent;
const base64Content = Buffer.from(fullMarkdown, 'utf8').toString('base64');
const imageBase64 = imageData.data[0].b64_json;

// GitHub API URL 구성 (TODO: GITHUB_REPO_NAME을 실제 저장소 이름으로 교체)
const GITHUB_BASE = 'https://api.github.com/repos/ineco812/family-tax-website/contents/';
const gitlabImageUrl = GITHUB_BASE + 'public%2Fimages%2Fposts%2F' + encodeURIComponent(imageFilename);
const gitlabFileUrl = GITHUB_BASE + 'src%2Fcontent%2Fposts%2F' + encodeURIComponent(prevData.slug + '.md');

return [{
  json: {
    title: prevData.title,
    slug: prevData.slug,
    filePath: 'src/content/posts/' + prevData.slug + '.md',
    fullMarkdown: fullMarkdown,
    base64Content: base64Content,
    imagePath: imagePath,
    imageFilename: imageFilename,
    imageBase64: imageBase64,
    gitlabImageUrl: gitlabImageUrl,
    gitlabFileUrl: gitlabFileUrl,
    keyword: prevData.keyword,
    dateStr: prevData.dateStr
  }
}];
